    "title": "LongAnswerPanel",
    "pkg": "panel.zillionaire",
    "group": "zillionaire",
    "file": "deobfuscated/panel/zillionaire/LongAnswerPanel.as",
    "cls": "LongAnswerPanel",
    "parent": "MallPanel",
